SELECT Montage.[Element Nr], Montage.[Anoden Nr], Montage.[Kathoden Nr], Montage.Membrantyp, Montage.[Membran Nr], Montage.[Elektroden Abstand], Montage.[Montage Datum], Montage.Remarks, Montage.Elektrolyseur, Montage.Position, Montage.[Einschalt Datum], Montage.[Ausschalt Datum], Montage.DOL, Montage.[Demontage Datum], Montage.Gruppe, Montage.Abschaltgrund, Montage.[Anode Coating], Montage.[Anode Electrode], Montage.[Anode Shell], Montage.[Cathode Coating], Montage.[Cathode Electrode], Montage.[Cathode Shell], Montage.[Info Membrane], Montage.Generation
FROM Montage
WHERE (((Montage.[Montage Datum]) Is Not Null) AND ((Montage.[Demontage Datum]) Is Null));
